<?php
require_once dirname(__DIR__).'/app/helpers.php';require_auth();require_once dirname(__DIR__).'/app/Services/BillPaymentService.php';$u=auth_user();$db=Database::connection();$svc=new BillPaymentService($db);$error=null;$success=null;$challenge=null;$accounts=[];$s=$db->prepare('SELECT a.id,a.account_number,a.available_balance,at.currency,at.name type_name FROM accounts a JOIN account_types at ON at.id=a.account_type_id WHERE a.user_id=? AND a.status="active" ORDER BY a.id');$s->execute([(int)$u['id']]);$accounts=$s->fetchAll();
try{if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';if($action==='initiate'){$key='BILLWEB-'.bin2hex(random_bytes(12));$challenge=$svc->initiate((int)$u['id'],(int)$_POST['account_id'],(int)$_POST['biller_id'],$_POST['customer_reference']??'',$_POST['amount']??'',$_POST['pin']??'',$key);$success=$challenge['is_existing']?t('Existing payment request found.'):t('Payment initiated. The OTP is displayed below.');}elseif($action==='confirm'){$ref=trim($_POST['reference']);$svc->confirm($ref,(int)$u['id'],$_POST['otp']??'');$success=t('Bill payment completed successfully.').(' '.t('Reference').': '.$ref);}elseif($action==='cancel'){$svc->cancel(trim($_POST['reference']),(int)$u['id']);$success=t('Payment cancelled.');}}}catch(Throwable $e){$error=$e->getMessage();}$billers=$svc->billers();$recent=$svc->recent((int)$u['id']);$totalBalance=0;foreach($accounts as $a)$totalBalance+=(float)$a['available_balance'];$pageTitle=t('Bill Payments');$currentPage='payments';require __DIR__.'/partials/header.php';require __DIR__.'/partials/sidebar.php';?>
<div class="d-flex justify-content-between align-items-center mb-4"><div><h3 class="fw-bold mb-1"><?=e(t('Bill Payments'))?></h3><p class="text-muted mb-0"><?=e(t('Pay electricity, internet, cable, airtime, data and water bills.'))?></p></div><a href="<?=url('scheduled-payments.php')?>" class="btn btn-outline-primary"><?=e(t('Scheduled Payments'))?></a></div>
<?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif;?>
<?php if($challenge&&!empty($challenge['otp'])):?><div class="alert alert-warning"><b><?=e(t('One-Time Password'))?>:</b> <span class="font-monospace fs-5"><?=e($challenge['otp'])?></span><div class="small mt-1"><?=e(t('Expires:'))?> <?=e($challenge['expires_at'])?></div><hr><form method="post" class="row g-2 align-items-end"><?=csrf_field()?><input type="hidden" name="action" value="confirm"><input type="hidden" name="reference" value="<?=e($challenge['reference'])?>"><div class="col-md-4"><label class="form-label"><?=e(t('Enter OTP'))?></label><input name="otp" class="form-control" maxlength="6" required></div><div class="col-auto"><button class="btn btn-success"><?=e(t('Confirm Payment'))?></button></div></form></div><?php endif;?>
<div class="row g-4"><div class="col-lg-5"><div class="card border-0 shadow-sm"><div class="card-header bg-white fw-bold"><?=e(t('Make a Payment'))?></div><div class="card-body"><form method="post" class="row g-3"><?=csrf_field()?><input type="hidden" name="action" value="initiate"><div class="col-12"><label class="form-label"><?=e(t('From Account'))?></label><select name="account_id" class="form-select" required><option value=""><?=e(t('Select account'))?></option><?php foreach($accounts as $a):?><option value="<?=$a['id']?>"><?=e($a['account_number'])?> — <?=e($a['type_name'])?> ($<?=number_format((float)$a['available_balance'],2)?>)</option><?php endforeach;?></select></div><div class="col-12"><label class="form-label"><?=e(t('Service'))?></label><select name="biller_id" class="form-select" required><option value=""><?=e(t('Select service'))?></option><?php foreach($billers as $b):?><option value="<?=$b['id']?>"><?=e(ucfirst($b['category']))?> — <?=e($b['name'])?></option><?php endforeach;?></select></div><div class="col-md-7"><label class="form-label"><?=e(t('Customer / Meter / Phone Reference'))?></label><input name="customer_reference" class="form-control" maxlength="120" required></div><div class="col-md-5"><label class="form-label"><?=e(t('Amount'))?></label><input name="amount" type="number" step="0.01" min="1" class="form-control" required></div><div class="col-12"><label class="form-label"><?=e(t('Transaction PIN'))?></label><input name="pin" type="password" inputmode="numeric" maxlength="6" class="form-control" required></div><div class="col-12"><button class="btn btn-primary w-100"><?=e(t('Continue to OTP'))?></button></div></form></div></div></div><div class="col-lg-7"><div class="card border-0 shadow-sm"><div class="card-header bg-white fw-bold"><?=e(t('Recent Bill Payments'))?></div><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th><?=e(t('Service'))?></th><th><?=e(t('Reference'))?></th><th><?=e(t('Amount'))?></th><th><?=e(t('Status'))?></th><th><?=e(t('Date'))?></th></tr></thead><tbody><?php if(!$recent):?><tr><td colspan="5" class="text-center text-muted py-4"><?=e(t('No bill payments yet.'))?></td></tr><?php else:foreach($recent as $p):?><tr><td><?=e($p['biller_name'])?></td><td class="font-monospace small"><?=e($p['reference'])?><div class="text-muted"><?=e($p['customer_reference'])?></div></td><td>$<?=number_format((float)$p['amount'],2)?></td><td><span class="badge text-bg-<?=in_array($p['status'],['completed'])?'success':($p['status']==='pending'?'warning':'secondary')?>"><?=e(tx_label($p['status']))?></span></td><td class="small text-muted"><?=e(format_date($p['created_at'],'M d, Y H:i'))?></td></tr><?php endforeach;endif;?></tbody></table></div></div></div></div><?php require __DIR__.'/partials/footer.php';?>
